routeHelpers.control:
def control(b):
    if b.get('action') == 'acquire':
        return runtime.acquire_control(b.get('owner', ''))
    if b.get('action') == 'release':
        return runtime.release_control(b.get('owner', ''))
    raise ValueError('action must be acquire or release')

routeHelpers.degrade:
def degrade(b):
    if not isinstance(b, dict) or set(b) != {'reason'}:
        raise ValueError('a degraded report accepts only a reason')
    return runtime.report_degraded(b['reason'])

routeHelpers.recovery:
def recovery(b, action):
    if not isinstance(b, dict):
        raise ValueError('recovery requires a JSON object')
    id_ = b.get('id')
    if action == 'start':
        job, context = (b.get('job'), b.get('context', ''))
        if job is not None and (not isinstance(job, str)) or not isinstance(context, str):
            raise ValueError('recovery context and job must be text')
        return runtime.begin_recovery(job, context)
    if action == 'complete':
        task, claim = (b.get('task'), b.get('claim'))
        if any((not isinstance(value, str) or not 0 < len(value.strip()) <= 4000 for value in (task, claim))):
            raise ValueError('task recovery review requires the operator task and EH conclusion')
        return runtime.begin_task_recovery_review(task.strip(), claim.strip())
    if not isinstance(id_, str) or not id_:
        raise ValueError('recovery requires its attempt ID')
    if action == 'clock':
        owner, operation, review = (b.get('owner'), b.get('operation'), b.get('reviewId'))
        if not isinstance(owner, str) or not owner or len(owner) > 100 or (operation not in ('pause', 'renew', 'release')) or (review is not None and (not isinstance(review, str) or not review)):
            raise ValueError('invalid recovery clock lease')
        return runtime.recovery_clock(id_, review, owner, operation)
    if action in ('analyze', 'rgbd', 'review'):
        review = b.get('reviewId')
        if review is not None and (not isinstance(review, str) or not review):
            raise ValueError('invalid recovery review ID')
        if action == 'rgbd':
            camera = b.get('camera')
            if camera is not None and (not isinstance(camera, str) or len(camera) > 100):
                raise ValueError('invalid robot camera name')
            return runtime.capture_recovery_rgbd(id_, review, camera)
        if action == 'analyze':
            code, ref = (b.get('code'), b.get('ref'))
            if not isinstance(code, str) or (ref is not None and (not isinstance(ref, str))):
                raise ValueError('analysis requires Python source and accepts one sample reference')
            return runtime.analyze_recovery(id_, code, review, ref)
        if review is None:
            raise ValueError('review completion requires a review ID')
        report = b.get('report')
        if report is not None:
            if not isinstance(report, dict) or set(report) - {'taskCompleted'} != {'verdict', 'reason', 'evidence'} or ('taskCompleted' in report and (not isinstance(report['taskCompleted'], bool))) or (report['verdict'] not in ('resolved', 'unresolved', 'insufficient_evidence')) or (not isinstance(report['reason'], str)) or (not 0 < len(report['reason'].strip()) <= 4096) or (not isinstance(report['evidence'], list)) or (len(report['evidence']) > 16) or any((not isinstance(ref, str) or not 0 < len(ref) <= 100 for ref in report['evidence'])):
                raise ValueError('invalid recovery review report')
        return runtime.finish_recovery_review(id_, review, report)
    if action == 'finish':
        completed = b.get('completed')
        if not isinstance(completed, bool):
            raise ValueError('diagnosis completion must be boolean')
        report = b.get('report')
        if completed and (not isinstance(report, dict) or set(report) != {'cause', 'evidence', 'recommendation', 'verification'} or any((not isinstance(value, str) or not 0 < len(value.strip()) <= 4096 for value in report.values()))):
            raise ValueError('a completed diagnosis requires a diagnosis report')
        return runtime.finish_recovery_diagnosis(id_, completed, report)
    refs = b.get('referenceBacks', [])
    if not isinstance(refs, list) or len(refs) > 2 or (not all((isinstance(ref, str) for ref in refs))):
        raise ValueError('referenceBacks must contain at most two Ego-State IDs')
    return runtime.begin_recovery_review(id_, refs)

routeHelpers.report:
def report(b):
    message = str(b.get('message', '')).strip()
    if not message:
        raise ValueError('an alert needs a message')
    return runtime.alert(message, str(b.get('source', 'agent')), str(b.get('level', 'blocked')), goal=str(b.get('goal') or ''), step=str(b.get('step') or ''), diagnosis=str(b.get('diagnosis') or ''))

routeHelpers.view_frame:
def view_frame(q):
    frame = runtime.view.latest(int(q['after']) if q.get('after') else None)
    if frame is not None:
        return frame_response(frame, runtime.view.status())
    status = runtime.view.status()
    if status['settings'] is None:
        raise HttpError(409, 'the ego view is not configured; POST /ego/view first')
    if status['error'] and status['frame'] is None:
        raise HttpError(503, f"the ego view cannot render: {status['error']}")
    return NO_CONTENT

